krb5_error_code validate_kdc_public_key_identifier(krb5_context context, pkinit_plg_crypto_context plg_cryptoctx, pkinit_req_crypto_context req_cryptoctx, pkinit_identity_crypto_context id_cryptoctx, unsigned char *pdid_buf, unsigned int pkid_len, int *valid_kdcPkId) {
    krb5_error_code ret = 0;
    unsigned char *decoded_data = NULL;
    size_t decoded_len = 0;

    if (!context || !plg_cryptoctx || !req_cryptoctx || !id_cryptoctx || !pdid_buf || !valid_kdcPkId) {
        return KRB5_BAD_MALLOC;
    }

    if (pkid_len == 0) {
        *valid_kdcPkId = 0;
        return 0;
    }

    ret = decode_public_key_identifier(pdid_buf, pkid_len, &decoded_data, &decoded_len);
    if (ret != 0) {
        return ret;
    }

    if (!decoded_data || decoded_len == 0) {
        krb5_free_data(context, decoded_data);
        *valid_kdcPkId = 0;
        return KRB5_BAD_DATA;
    }

    ret = compare_with_kdc_certificate(decoded_data, decoded_len, plg_cryptoctx, req_cryptoctx, id_cryptoctx);
    if (ret != 0) {
        krb5_free_data(context, decoded_data);
        return ret;
    }

    *valid_kdcPkId = 1;

    krb5_free_data(context, decoded_data);
    return 0;
}
